using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
public enum StreetLegendMissionStage { HotelCombat, DrivingPursuit, Roadblock, Dismounting, PostRoadblockCombat, Complete }
public class StreetLegendMissionPhase : MonoBehaviour {
 public StreetLegendVehicleController vehicle; public GameObject drivingHUD,combatHUD,roadblockHUD; public PrototypeMobileHUD mobileHUD;
 public PrototypeFighterController player,roadblockFighter; public PrototypeOpponent roadblockOpponent;
 public Transform safeExitPoint,roadblockOpponentPoint; public StreetLegendMissionStage phase=StreetLegendMissionStage.HotelCombat;
 bool triggered,combatStarted,won,defeated;
 void Update(){if(phase!=StreetLegendMissionStage.PostRoadblockCombat)return;if(!won&&!defeated&&player&&player.Health<=0f){defeated=true;ShowDefeatPanel();}else if(!won&&!defeated&&roadblockOpponent&&roadblockOpponent.Health<=0){won=true;Finish();}}
 public void BeginPursuit(){if(phase!=StreetLegendMissionStage.HotelCombat)return;phase=StreetLegendMissionStage.DrivingPursuit;if(vehicle){vehicle.gameObject.SetActive(true);vehicle.SetDrivingEnabled(true);}if(drivingHUD)drivingHUD.SetActive(true);if(combatHUD)combatHUD.SetActive(false);if(mobileHUD)mobileHUD.SetHUDVisible(false);SetPlayerVisuals(false);}
 void SetPlayerVisuals(bool show){if(!player)return;foreach(var renderer in player.GetComponentsInChildren<Renderer>(true))renderer.enabled=show;}
 public void RoadblockReached(){if(phase!=StreetLegendMissionStage.DrivingPursuit||triggered)return;triggered=true;phase=StreetLegendMissionStage.Dismounting;if(vehicle){vehicle.StopVehicle();vehicle.SetDrivingEnabled(false);}if(drivingHUD)drivingHUD.SetActive(false);StartCoroutine(DismountHandoff());}
 IEnumerator DismountHandoff(){// Give the stopped vehicle a short cinematic beat before staging the fighters.
 yield return new WaitForSecondsRealtime(1.0f);
 if(player){if(safeExitPoint){player.transform.SetPositionAndRotation(safeExitPoint.position,safeExitPoint.rotation);}player.ResetVerticalMotion();player.enabled=true;SetPlayerVisuals(true);}
 if(roadblockFighter){roadblockFighter.gameObject.SetActive(true);if(roadblockOpponentPoint)roadblockFighter.transform.SetPositionAndRotation(roadblockOpponentPoint.position,roadblockOpponentPoint.rotation);roadblockFighter.enabled=true;}
 if(roadblockOpponent){roadblockOpponent.gameObject.SetActive(true);if(player)roadblockOpponent.SetTarget(player.transform);}
 if(player&&roadblockFighter)player.SetOpponent(roadblockFighter.transform);if(mobileHUD)mobileHUD.RefreshOpponent();
 yield return new WaitForSecondsRealtime(.35f);BeginRoadblockCombat();}
 public void BeginRoadblockCombat(){if(phase!=StreetLegendMissionStage.Dismounting||combatStarted)return;combatStarted=true;phase=StreetLegendMissionStage.PostRoadblockCombat;if(combatHUD)combatHUD.SetActive(true);if(mobileHUD)mobileHUD.SetHUDVisible(true);if(roadblockHUD)roadblockHUD.SetActive(true);}
 public void Finish(){if(phase!=StreetLegendMissionStage.PostRoadblockCombat)return;phase=StreetLegendMissionStage.Complete;if(roadblockHUD)roadblockHUD.SetActive(false);if(combatHUD)combatHUD.SetActive(false);if(mobileHUD)mobileHUD.SetHUDVisible(false);if(player)player.enabled=false;if(roadblockOpponent)roadblockOpponent.enabled=false;BuildOutcomeOverlay(true);}
 void ShowDefeatPanel(){phase=StreetLegendMissionStage.Complete;if(roadblockHUD)roadblockHUD.SetActive(false);if(mobileHUD)mobileHUD.SetHUDVisible(false);if(player)player.enabled=false;if(roadblockOpponent)roadblockOpponent.enabled=false;BuildOutcomeOverlay(false);}
 void BuildOutcomeOverlay(bool victory){Time.timeScale=1f;var root=new GameObject("Level Outcome Overlay",typeof(Canvas),typeof(CanvasScaler));var canvas=root.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=80;var scaler=root.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);var panel=new GameObject("Outcome Panel",typeof(RectTransform),typeof(Image));panel.transform.SetParent(root.transform,false);var rect=panel.GetComponent<RectTransform>();rect.anchorMin=new Vector2(.25f,.25f);rect.anchorMax=new Vector2(.75f,.75f);rect.offsetMin=rect.offsetMax=Vector2.zero;panel.GetComponent<Image>().color=new Color(.035f,.07f,.12f,.94f);var label=new GameObject("Outcome Title",typeof(RectTransform),typeof(Text));label.transform.SetParent(panel.transform,false);var lr=label.GetComponent<RectTransform>();lr.anchorMin=new Vector2(.05f,.55f);lr.anchorMax=new Vector2(.95f,.95f);lr.offsetMin=lr.offsetMax=Vector2.zero;var txt=label.GetComponent<Text>();txt.font=Resources.GetBuiltinResource<Font>("Arial.ttf");txt.text=victory?"LEVEL 1 COMPLETE\nROADBLOCK CLEARED":"DEFEATED\nTRY AGAIN";txt.fontSize=48;txt.fontStyle=FontStyle.Bold;txt.alignment=TextAnchor.MiddleCenter;txt.color=Color.white;var buttonObj=new GameObject("Replay Button",typeof(RectTransform),typeof(Image),typeof(Button));buttonObj.transform.SetParent(panel.transform,false);var br=buttonObj.GetComponent<RectTransform>();br.anchorMin=new Vector2(.3f,.12f);br.anchorMax=new Vector2(.7f,.42f);br.offsetMin=br.offsetMax=Vector2.zero;buttonObj.GetComponent<Image>().color=new Color(.12f,.48f,.72f);buttonObj.GetComponent<Button>().onClick.AddListener(()=>SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex));var bt=new GameObject("Button Label",typeof(RectTransform),typeof(Text));bt.transform.SetParent(buttonObj.transform,false);var btr=bt.GetComponent<RectTransform>();btr.anchorMin=Vector2.zero;btr.anchorMax=Vector2.one;btr.offsetMin=btr.offsetMax=Vector2.zero;var btext=bt.GetComponent<Text>();btext.font=Resources.GetBuiltinResource<Font>("Arial.ttf");btext.text=victory?"REPLAY LEVEL":"RETRY";btext.fontSize=32;btext.fontStyle=FontStyle.Bold;btext.alignment=TextAnchor.MiddleCenter;btext.color=Color.white;}
 public void ResetMission(){StopAllCoroutines();Time.timeScale=1f;triggered=combatStarted=won=defeated=false;phase=StreetLegendMissionStage.HotelCombat;SetPlayerVisuals(true);if(player){player.enabled=true;player.ResetVerticalMotion();}if(roadblockFighter){roadblockFighter.gameObject.SetActive(false);}if(roadblockOpponent){roadblockOpponent.enabled=false;}if(vehicle){vehicle.StopVehicle();vehicle.SetDrivingEnabled(false);vehicle.gameObject.SetActive(false);}if(drivingHUD)drivingHUD.SetActive(false);if(roadblockHUD)roadblockHUD.SetActive(false);if(combatHUD)combatHUD.SetActive(true);if(mobileHUD)mobileHUD.SetHUDVisible(true);}
}